  function byId(id){return document.getElementById(id);}
  function q(sel,root){return (root||document).querySelector(sel);}
  function qa(sel,root){return Array.prototype.slice.call((root||document).querySelectorAll(sel));}
  function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function imageSrc(key){return key?(IMAGE_DATA[key]||key):'';}
  function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
  function shuffle(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}return a;}
  function blockById(id){return BLOCKS.find(function(x){return x.id===id;});}
  function lessonById(id){return LESSONS.find(function(x){return x.id===id;});}
  function blockLessons(id){return LESSONS.filter(function(x){return x.block===id;});}
  function lessonQuestions(id){return EXERCISES.filter(function(x){return x.lesson===id;});}
  function blockQuestions(id){return EXERCISES.filter(function(x){return x.block===id;});}
  function exerciseById(id){return EXERCISES.find(function(x){return x.id===id;});}

  function validateData(){
    var ids={},prompts={};
    if(BLOCKS.length!==6)throw new Error('Stilkunde: Blockzahl');
    if(LESSONS.length!==30)throw new Error('Stilkunde: Lektionszahl');
    if(EXERCISES.length!==198)throw new Error('Stilkunde: Aufgabenzahl');
    EXERCISES.forEach(function(x){
      if(ids[x.id])throw new Error('Doppelte Stilkunde-ID: '+x.id); ids[x.id]=1;
      var p=String(x.prompt||'').trim().toLowerCase(); if(prompts[p])throw new Error('Doppelte Stilkunde-Frage: '+x.prompt); prompts[p]=1;
      if(!Array.isArray(x.options)||x.options.length!==4||new Set(x.options).size!==4)throw new Error('Antwortoptionen: '+x.id);
      if(x.correct<0||x.correct>3)throw new Error('Lösung: '+x.id);
      if(!x.src||!SOURCE_NOTES[x.src])throw new Error('Quelle: '+x.id);
      if(x.image&&String(x.image).indexOf('stilkunde-img/')!==0)throw new Error('Bildpfad: '+x.id);
      if(x.image&&!IMAGE_DATA[x.image])throw new Error('Bilddaten fehlen: '+x.id);
    });
    LESSONS.forEach(function(l){if(!LEARNING[l.id]||LEARNING[l.id].length<2)throw new Error('Lernkarten: '+l.id);if(lessonQuestions(l.id).length<6)throw new Error('Lektionsaufgaben: '+l.id);});
    var expected=[0,36,33,33,33,33,30];for(var b=1;b<=6;b++){if(blockQuestions(b).length!==expected[b])throw new Error('Blockaufgaben: '+b+'='+blockQuestions(b).length);}
    return {ok:true,exerciseCount:EXERCISES.length,lessonCount:LESSONS.length,blockCount:BLOCKS.length,activeBlocks:ACTIVE_BLOCKS,imageExerciseCount:EXERCISES.filter(function(x){return !!x.image;}).length};
  }
  var VALIDATION=validateData();

  function defaultState(){return {version:VERSION,unlockedBlock:1,lesson:{},blockTests:{},finalTest:{best:0,passed:false,runs:0},mistakes:{},seen:{},lastBlock:1,lastLesson:null,updatedAt:Date.now()};}
  function sanitizeState(s){if(!s||typeof s!=='object')return defaultState();s.version=VERSION;s.unlockedBlock=clamp(Number(s.unlockedBlock)||1,1,ACTIVE_BLOCKS);s.lesson=s.lesson||{};s.blockTests=s.blockTests||{};s.finalTest=s.finalTest||{best:0,passed:false,runs:0};s.mistakes=s.mistakes||{};s.seen=s.seen||{};for(var bi=1;bi<ACTIVE_BLOCKS;bi++){if(s.blockTests[bi]&&s.blockTests[bi].passed)s.unlockedBlock=Math.max(s.unlockedBlock,bi+1);}s.lastBlock=clamp(Number(s.lastBlock)||1,1,ACTIVE_BLOCKS);return s;}
  function loadState(){try{return sanitizeState(JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'));}catch(e){return defaultState();}}
  var state=typeof localStorage!=='undefined'?loadState():defaultState();
  function saveState(){state.updatedAt=Date.now();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){}updateLauncher();}
  function lState(id){return state.lesson[id]||(state.lesson[id]={best:0,passed:false,runs:0,read:false});}
  function bState(id){return state.blockTests[id]||(state.blockTests[id]={best:0,passed:false,runs:0});}
  function fState(){return state.finalTest||(state.finalTest={best:0,passed:false,runs:0});}
