  function makeRoot(){if(root)return;injectStyle();root=document.createElement('main');root.id='styleTrainer';root.className='section hidden';var app=q('.app'),footer=app&&q('footer.copyright',app);if(app){if(footer)app.insertBefore(root,footer);else app.appendChild(root);}}
  function hideOther(){['home','library','quiz','review','stats','examV13','binderTrainer','substrateTrainer','colorTrainer'].forEach(function(id){var e=byId(id);if(e)e.classList.add('hidden');});if(root)root.classList.remove('hidden');var hb=byId('homeBtn');if(hb)hb.classList.remove('hidden');try{window.scrollTo({top:0,behavior:'smooth'});}catch(e){}}
  function close(){if(root)root.classList.add('hidden');current=null;}
  function open(){makeRoot();hideOther();renderHome();}
  function findDepthGroup(){var dash=byId('v17Dashboard');if(!dash)return null;var groups=qa('.v17Group',dash);return groups.find(function(g){var t=q('.v17GroupTitle',g);return t&&/Vertiefen/i.test(t.textContent||'');})||null;}
  function injectLauncher(){if(byId('stLauncher'))return;var dash=byId('v17Dashboard');if(!dash)return;var section=findDepthGroup();if(!section){section=document.createElement('section');section.className='v17Group';section.innerHTML='<div class="v17GroupHead"><div class="v17GroupTitle">Vertiefen</div><div class="v17GroupHint">Thema wirklich verstehen</div></div><div class="v17ActionGrid"></div>';var utility=q('.v17Utility',dash);if(utility)dash.insertBefore(section,utility);else dash.appendChild(section);}var grid=q('.v17ActionGrid',section);if(!grid)return;var b=document.createElement('button');b.type='button';b.id='stLauncher';b.className='v17Action stLaunch';b.innerHTML='<span class="v17ActionIcon" aria-hidden="true">🏛️</span><span><span class="v17ActionTitle">Stilkunde-Trainer</span><span class="v17ActionText">Erkennen · zuordnen · am Bild prüfen.</span></span><span class="v17ActionArrow">›</span>';b.onclick=open;grid.appendChild(b);updateLauncher();}
  function updateLauncher(){var b=byId('stLauncher');if(!b)return;var t=q('.v17ActionText',b);if(t)t.innerHTML='Erkennen · zuordnen · am Bild prüfen.<span class="stLaunchProgress">'+completedLessons()+'/'+LESSONS.length+' Lektionen bestanden</span>';}
  function blockUnlocked(id){return id<=state.unlockedBlock;}
  function lessonUnlocked(l){if(!blockUnlocked(l.block))return false;var ls=blockLessons(l.block),idx=ls.findIndex(function(x){return x.id===l.id;});return idx<=0||lessonPassed(ls[idx-1].id);}
  function header(eye,title,sub){return '<div class="card stHeader"><div class="stHeaderTop"><div><div class="stEye">'+esc(eye)+'</div><div class="stHeaderTitle">'+esc(title)+'</div><div class="stHeaderSub">'+esc(sub)+'</div></div><button class="btn" id="stBack">← Zurück</button></div></div>';}
  function renderHome(){makeRoot();current=null;var done=completedLessons(),pct=Math.round(100*done/LESSONS.length),blocksDone=BLOCKS.filter(function(b){return blockPassed(b.id);}).length;root.innerHTML='<div class="card stHead"><div class="stTop"><div><div class="stEye">HF 1 · Stil, Form & Gestaltung</div><div class="stTitle">Stilkunde-Trainer 🏛️</div><div class="stLead">Baustile und Architekturbegriffe verstehen, Säulen und Ornamente sicher benennen, Heraldik einordnen und die wichtigsten Elemente anschließend direkt am Bild erkennen.</div></div><div class="stMeta"><span class="badge">'+EXERCISES.length+' Aufgaben</span><span class="badge">'+LESSONS.length+' Lektionen</span><span class="badge">6 Blöcke</span></div></div><div class="stProgress"><span style="width:'+pct+'%"></span></div></div><div class="stStats"><div class="stStat"><span>LEKTIONEN</span><strong>'+done+'/'+LESSONS.length+'</strong></div><div class="stStat"><span>BLÖCKE</span><strong>'+blocksDone+'/6</strong></div><div class="stStat"><span>FEHLERPOOL</span><strong>'+totalMistakes()+'</strong></div><div class="stStat"><span>BESTEHEN</span><strong>'+PASS_PCT+' %</strong></div></div><div class="stBlocks" id="stBlocks"></div><div class="stBlockTest"><span><strong>Stilkunde-Gesamttest</strong><div>'+FINAL_TEST_SIZE+' Aufgaben · alle 6 Blöcke · Bestehen ab '+PASS_PCT+' %</div></span><button class="btn primary" id="stFinalTest">Gesamttest starten</button></div><div class="stActions"><button class="btn" id="stErrors">↺ Fehler wiederholen</button><button class="btn" id="stReset">Trainer zurücksetzen</button></div>';
    var grid=byId('stBlocks');BLOCKS.forEach(function(b){var unlocked=blockUnlocked(b.id),passed=blockPassed(b.id),el=document.createElement('button');el.type='button';el.className='stBlock'+(passed?' done':'');el.disabled=!unlocked;el.innerHTML='<span class="stIcon">'+b.icon+'</span><span><span class="stBlockTitle">'+esc(b.title)+'</span><span class="stBlockSub">'+esc(b.sub)+'</span></span><span class="stState">'+(passed?'BESTANDEN':unlocked?'OFFEN':'GESPERRT')+'</span>';el.onclick=function(){openBlock(b.id);};grid.appendChild(el);});
    var ft=byId('stFinalTest');ft.disabled=!allBlocksPassed();ft.onclick=startFinalTest;byId('stErrors').disabled=totalMistakes()===0;byId('stErrors').onclick=startMistakeRound;byId('stReset').onclick=resetState;
  }
  function openBlock(id){if(!blockUnlocked(id))return renderHome();state.lastBlock=id;saveState();var b=blockById(id),ls=blockLessons(id),bs=bState(id);root.innerHTML=header('Block '+id,b.title,b.sub)+'<div class="stLessonGrid" id="stLessonGrid"></div><div class="stBlockTest"><span><strong>Block-Check</strong><div>12 Aufgaben · Basis, Verstehen und Anwenden · Bestwert '+bs.best+' %</div></span><button class="btn primary" id="stBlockTestBtn">Block-Check starten</button></div>';byId('stBack').onclick=renderHome;var grid=byId('stLessonGrid');ls.forEach(function(l,i){var st=lState(l.id),un=lessonUnlocked(l),el=document.createElement('button');el.type='button';el.className='stLesson'+(st.passed?' passed':'');el.disabled=!un;el.innerHTML='<span class="stLessonNum">'+(i+1)+'</span><span><span class="stLessonTitle">'+esc(l.title)+'</span><span class="stLessonSub">'+esc(l.sub)+'</span></span><span class="stLessonScore">'+(st.passed?'✓ '+st.best+'%':un?(st.runs?st.best+'%':'START'):'🔒')+'</span>';el.onclick=function(){openLesson(l.id);};grid.appendChild(el);});var bt=byId('stBlockTestBtn');bt.disabled=!blockLessonsPassed(id);bt.onclick=function(){startBlockTest(id);};}
  function openLesson(id){var l=lessonById(id);if(!l)return;state.lastLesson=id;saveState();current={kind:'learn',lesson:id,slide:0};renderLearning();}
  function renderLearning(){var l=lessonById(current.lesson),cards=LEARNING[l.id],i=current.slide||0,card=cards[i],img=card.image?'<img class="stImage" src="'+esc(imageSrc(card.image))+'" alt="Stilkunde-Abbildung">':'';root.innerHTML=header('Block '+l.block+' · Lernen',l.title,l.sub)+'<div class="card stLearn"><div class="stLearnCard">'+img+'<h3>'+esc(card.title)+'</h3><p>'+esc(card.text)+'</p><div class="stMemo">'+esc(card.memo)+'</div></div><div class="stLearnNav"><button class="btn" id="stPrev" '+(i===0?'disabled':'')+'>← Vorheriges</button><button class="btn primary" id="stLearnNext">'+(i===cards.length-1?'Zur Übung':'Weiter →')+'</button></div></div>';byId('stBack').onclick=function(){openBlock(l.block);};byId('stPrev').onclick=function(){if(current.slide>0){current.slide--;renderLearning();}};byId('stLearnNext').onclick=function(){if(current.slide<cards.length-1){current.slide++;renderLearning();return;}lState(l.id).read=true;saveState();startLessonQuiz(l.id);};}
  function chooseQuestions(pool,count){var a=pool.map(function(item){return {item:item,seen:Number(state.seen[item.id])||0,r:Math.random()};});a.sort(function(x,y){return x.seen-y.seen||x.r-y.r;});return a.slice(0,Math.min(count,a.length)).map(function(x){return x.item;});}
  function prepared(item){var opts=item.options.map(function(t,i){return {text:t,orig:i};});opts=shuffle(opts);return {source:item,display:opts,correctPos:opts.findIndex(function(x){return x.orig===item.correct;})};}
  function startLessonQuiz(id){var l=lessonById(id),items=chooseQuestions(lessonQuestions(id),LESSON_ROUND).map(prepared);items.forEach(function(x){state.seen[x.source.id]=(Number(state.seen[x.source.id])||0)+1;});saveState();current={kind:'quiz',mode:'lesson',lesson:id,block:l.block,items:items,index:0,score:0,answered:false};renderQuestion();}
  function startBlockTest(id){var pool=blockQuestions(id),byLevel={basis:[],verstehen:[],anwenden:[]};pool.forEach(function(x){(byLevel[x.level]||byLevel.verstehen).push(x);});var pick=[];[['basis',4],['verstehen',4],['anwenden',4]].forEach(function(spec){pick=pick.concat(chooseQuestions(byLevel[spec[0]],spec[1]));});pick=shuffle(pick).slice(0,BLOCK_TEST_SIZE);pick.forEach(function(x){state.seen[x.id]=(Number(state.seen[x.id])||0)+1;});saveState();current={kind:'quiz',mode:'block',block:id,items:pick.map(prepared),index:0,score:0,answered:false};renderQuestion();}
  function startFinalTest(){if(!allBlocksPassed())return renderHome();var pick=[];for(var b=1;b<=ACTIVE_BLOCKS;b++){var pool=blockQuestions(b),byLevel={basis:[],verstehen:[],anwenden:[]};pool.forEach(function(x){(byLevel[x.level]||byLevel.verstehen).push(x);});pick=pick.concat(chooseQuestions(byLevel.basis,1),chooseQuestions(byLevel.verstehen,1),chooseQuestions(byLevel.anwenden,2));}pick=shuffle(pick).slice(0,FINAL_TEST_SIZE);pick.forEach(function(x){state.seen[x.id]=(Number(state.seen[x.id])||0)+1;});saveState();current={kind:'quiz',mode:'final',items:pick.map(prepared),index:0,score:0,answered:false};renderQuestion();}
  function startMistakeRound(){var ids=Object.keys(state.mistakes).filter(function(id){return state.mistakes[id]&&state.mistakes[id].wrong>0&&exerciseById(id);});if(!ids.length)return renderHome();ids.sort(function(a,b){return (state.mistakes[b].wrong||0)-(state.mistakes[a].wrong||0);});current={kind:'quiz',mode:'mistakes',items:shuffle(ids.slice(0,10).map(exerciseById)).map(prepared),index:0,score:0,answered:false};renderQuestion();}
  function renderQuestion(){var c=current,item=c.items[c.index],src=item.source,eye=c.mode==='lesson'?'Lektionsübung':c.mode==='block'?'Block-Check':c.mode==='final'?'Gesamttest':'Fehlerwiederholung',sub=c.mode==='lesson'?lessonById(c.lesson).title:c.mode==='block'?blockById(c.block).title:c.mode==='final'?'Stilkunde · alle 6 Blöcke':'Unsichere Aufgaben erneut festigen',img=src.image?'<img class="stImage" src="'+esc(imageSrc(src.image))+'" alt="Stilkunde-Fragebild">':'';root.innerHTML=header(eye,sub,'Aufgabe '+(c.index+1)+' von '+c.items.length)+'<div class="card stQuiz"><div class="stQMeta"><span class="badge">'+(c.index+1)+' / '+c.items.length+'</span><span class="badge">'+esc(src.level.toUpperCase())+'</span></div>'+img+'<div class="stQuestion">'+esc(src.prompt)+'</div><div class="stAnswers" id="stAnswers"></div><div id="stFeedback"></div></div>';byId('stBack').onclick=function(){if(c.mode==='lesson')openBlock(c.block);else renderHome();};var box=byId('stAnswers');item.display.forEach(function(o,pos){var b=document.createElement('button');b.type='button';b.className='stAnswer';b.innerHTML='<span class="stLetter">'+String.fromCharCode(65+pos)+'</span><span>'+esc(o.text)+'</span>';b.onclick=function(){answer(pos,b);};box.appendChild(b);});}
  function answer(pos,btn){if(!current||current.answered)return;current.answered=true;var item=current.items[current.index],src=item.source,ok=pos===item.correctPos;if(ok)current.score++;var m=state.mistakes[src.id]||(state.mistakes[src.id]={wrong:0,right:0});if(ok){m.right++;if(m.wrong>0)m.wrong=Math.max(0,m.wrong-1);}else m.wrong++;saveState();qa('.stAnswer',byId('stAnswers')).forEach(function(b,i){b.disabled=true;if(i===item.correctPos)b.classList.add('correct');else if(b===btn)b.classList.add('wrong');});byId('stFeedback').innerHTML='<div class="stFeedback"><strong>'+(ok?'Richtig.':'Noch nicht.')+'</strong> '+(ok?'Die Zuordnung sitzt.':'Die richtige Antwort ist markiert.')+'<div class="stQuizActions"><button class="btn" id="stWhy">Warum?</button><button class="btn primary" id="stNext">'+(current.index+1<current.items.length?'Weiter':'Auswerten')+'</button></div><div class="stWhy hidden" id="stWhyBox">'+esc(src.why)+'</div></div>';byId('stWhy').onclick=function(){byId('stWhyBox').classList.toggle('hidden');};byId('stNext').onclick=nextQuestion;}
  function nextQuestion(){if(!current||!current.answered)return;if(current.index+1<current.items.length){current.index++;current.answered=false;renderQuestion();}else finishQuiz();}
  function finishQuiz(){var c=current,total=c.items.length,score=c.score,pct=Math.round(100*score/total),passed=pct>=PASS_PCT,title='',text='',again=function(){},overview=renderHome;if(c.mode==='lesson'){var st=lState(c.lesson);st.runs++;st.best=Math.max(st.best,pct);if(passed)st.passed=true;saveState();var l=lessonById(c.lesson);title=passed?'Lektion bestanden':'Lektion noch nicht bestanden';text='Bestwert: '+st.best+' %. '+(passed?'Die nächste Lektion ist freigeschaltet.':'Für das Bestehen brauchst du mindestens '+PASS_PCT+' %.');again=function(){startLessonQuiz(c.lesson);};overview=function(){openBlock(l.block);};}else if(c.mode==='block'){var bs=bState(c.block);bs.runs++;bs.best=Math.max(bs.best,pct);if(passed){bs.passed=true;if(c.block<ACTIVE_BLOCKS)state.unlockedBlock=Math.max(state.unlockedBlock,c.block+1);}saveState();title=passed?'Block bestanden':'Block noch nicht bestanden';text='Bestwert: '+bs.best+' %. '+(passed?(c.block<ACTIVE_BLOCKS?'Der nächste Lernblock ist freigeschaltet.':'Alle 6 Lernblöcke sind abgeschlossen. Jetzt ist der Stilkunde-Gesamttest freigeschaltet.'):'Für die Freischaltung brauchst du mindestens '+PASS_PCT+' %.');again=function(){startBlockTest(c.block);};}else if(c.mode==='final'){var fs=fState();fs.runs++;fs.best=Math.max(fs.best,pct);if(passed)fs.passed=true;saveState();title=passed?'Gesamttest bestanden':'Gesamttest noch nicht bestanden';text='Bestwert: '+fs.best+' %. '+(passed?'Stilkunde-Lernpfad inklusive Bildtraining ist bestanden.':'Für den Gesamttest brauchst du mindestens '+PASS_PCT+' %.');again=startFinalTest;}else{title='Fehlerrunde abgeschlossen';text='Richtig gelöste Fehler werden schrittweise aus dem Wiederholungspool abgebaut.';again=startMistakeRound;}root.innerHTML=header('Auswertung',title,pct+' % erreicht')+'<div class="card stResult"><div class="stScore">'+score+'/'+total+'</div><div class="stResultTitle">'+esc(title)+'</div><div class="stResultText">'+esc(text)+'</div><div class="stQuizActions" style="margin-top:16px"><button class="btn" id="stAgain">Wiederholen</button><button class="btn primary" id="stOverview">Weiter</button></div></div>';byId('stBack').onclick=overview;byId('stAgain').onclick=again;byId('stOverview').onclick=overview;current=null;updateLauncher();}
  function resetState(){if(!window.confirm('Stilkunde-Trainer wirklich zurücksetzen?\n\nNur der Fortschritt dieses Trainers wird gelöscht.'))return;state=defaultState();saveState();renderHome();}
  function hookHomeButton(){var b=byId('homeBtn');if(!b||b.dataset.stHooked==='1')return;b.addEventListener('click',function(){if(root&&!root.classList.contains('hidden'))close();});b.dataset.stHooked='1';}
  function exportState(){return JSON.parse(JSON.stringify(state));}
  function importState(s){if(!s||typeof s!=='object')return false;try{state=sanitizeState(JSON.parse(JSON.stringify(s)));saveState();return true;}catch(e){return false;}}
  function clearState(){try{localStorage.removeItem(STORAGE_KEY);}catch(e){}state=defaultState();updateLauncher();}
  function getState(){return exportState();}
  function boot(){makeRoot();injectLauncher();hookHomeButton();var tries=0,t=setInterval(function(){tries++;injectLauncher();hookHomeButton();if(byId('stLauncher')||tries>40)clearInterval(t);},120);}
  window.FachteilStyleTrainerV25={open:open,close:close,exportState:exportState,importState:importState,clearState:clearState,getState:getState,blocks:BLOCKS,lessons:LESSONS,exercises:EXERCISES,validation:VALIDATION,finalTestSize:FINAL_TEST_SIZE,sourceNotes:SOURCE_NOTES};
  if(typeof document!=='undefined'){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else setTimeout(boot,0);}
